import hashlib

def hash_partition(key, num_partitions=4):
    return int(hashlib.md5(key.encode()).hexdigest(), 16) % num_partitions

events = [
    {'key': 'user_10', 'seq': 1, 'action': 'login'},
    {'key': 'user_20', 'seq': 1, 'action': 'login'},
    {'key': 'user_10', 'seq': 2, 'action': 'add_to_cart'},
    {'key': 'user_10', 'seq': 3, 'action': 'checkout'},
]

# Enrutar a particiones
partition_queues = {i: [] for i in range(4)}
for ev in events:
    p = hash_partition(ev['key'])
    partition_queues[p].append(ev)

print('=== DISTRIBUCIÓN POR PARTICIONES ===')
for p, msgs in partition_queues.items():
    if msgs:
        print(f'Partición {p}: {[m["action"] for m in msgs]} (Key={msgs[0]["key"]})')
